    /**
     * Tests getting all Teams.
     *
     * @return    Collection
     */
    public List<Team> testGetAll() throws Throwable {
    LOGGER.info( "TeamTest:testGetAll() - Retrieving Collection of Teams:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Team : " );
    List<Team> collection  = null;

    try {
        // call the static get method on the TeamService
        collection = service.getAllTeam();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Team currEntity  = null;
            Iterator<Team> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getTeamId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

